// ═══════════════════════════════════════════════════════════════════════════
// ΟΙ ΜΕΤΑΒΛΗΤΕΣ CSS ΠΟΥ ΔΗΛΩΝΕΙ ΕΝΑ ΣΗΜΕΙΟ ΚΑΙ ΔΙΑΒΑΖΕΙ ΜΙΑ ΚΛΑΣΗ
//
// ΤΟ ΠΡΟΒΛΗΜΑ. Ο τύπος `CSSProperties` της React δέχεται μόνο γνωστές
// ιδιότητες. Μια μεταβλητή CSS (`--κάτι`) είναι έγκυρη σε κάθε περιηγητή και
// απορρίπτεται από τον μεταγλωττιστή, οπότε το μοτίβο «η κλάση κρατά τη
// συμπεριφορά, το σημείο δηλώνει την παράμετρο» ήταν αδύνατο να γραφτεί χωρίς
// `as CSSProperties` — δηλαδή χωρίς να σβήσει ΟΛΟΣ ο έλεγχος του αντικειμένου.
//
// ΤΟ ΜΗΤΡΩΟ ΕΙΝΑΙ ΚΛΕΙΣΤΟ ΕΠΙΤΗΔΕΣ. Δεν ανοίγει με `[key: string]`: τότε κάθε
// ορθογραφικό λάθος σε όνομα ιδιότητας θα περνούσε αθόρυβα. Κάθε μεταβλητή
// γράφεται εδώ ρητά, με το τι σημαίνει και ποια κλάση τη διαβάζει.
// ═══════════════════════════════════════════════════════════════════════════
import 'react';

declare module 'react' {
  interface CSSProperties {
    /** Το χρώμα γεμίσματος στην αιώρηση και στην εστίαση. Το διαβάζει η `.po-hov-fill`. */
    '--hov-fill'?: string;
    /** Το χρώμα περιγράμματος ΣΤΗΝ ΗΡΕΜΙΑ. Το διαβάζουν η `.po-hov-accent` και η `.po-choice`. */
    '--hov-edge-rest'?: string;
    /** Το χρώμα κειμένου ΣΤΗΝ ΗΡΕΜΙΑ. Το διαβάζει η `.po-hov-accent`. */
    '--hov-ink-rest'?: string;
    /** Το φόντο της γραμμής ΣΤΗΝ ΗΡΕΜΙΑ. Το διαβάζει η `.po-hov-row`. */
    '--hov-row-rest'?: string;
    /** Το φόντο της επιλογής ΣΤΗΝ ΗΡΕΜΙΑ. Το διαβάζει η `.po-choice`. */
    '--hov-choice-rest'?: string;
    /** Το κενό ανάμεσα σε βελάκι και τίτλο πτυσσόμενης κεφαλίδας. Το διαβάζει η `.acc-toggle`· προεπιλογή 8. */
    '--acc-gap'?: string;
    /** Το γέμισμα της πτυσσόμενης κεφαλίδας, όταν είναι ολόκληρη γραμμή. Το διαβάζει η `.acc-toggle`· προεπιλογή 0. */
    '--acc-pad'?: string;
    /** Το πλάτος κάτω από το οποίο ο πίνακας αρχίζει να κυλά οριζόντια. Το διαβάζει η `.po-table`. */
    '--tbl-min'?: string;
    /** Το μέγεθος κειμένου του πίνακα. Το διαβάζει η `.po-table`· προεπιλογή 13. */
    '--tbl-fs'?: string;
  }
}
